import { readFile } from "node:fs/promises"
import { prepareReviewSource } from "../../shared/review-sources.ts"
import type { Hospital } from "../../shared/run-posted-document.ts"
import { normalized } from "./validate.ts"

export type ServiceAreaReference = {
  status: "verified" | "missing"
  requiredCounties: string[]
  evidence: { snapshot_id: string; sourceUrl: string; sha256: string; locator: string; quote: string }[]
  limitations: string[]
}

// Optional operator-supplied reference packet, never generated by the reviewing
// agent. The packet pins a facility-specific rule and its original source bytes.
export async function loadServiceAreaReference(hospital: Hospital, reviewDate: string, project: string, path?: string): Promise<ServiceAreaReference> {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(reviewDate) || !Number.isFinite(Date.parse(reviewDate))) throw new Error("Invalid service-area review date")
  if (!path) return { status: "missing", requiredCounties: [], evidence: [], limitations: [
    "No dated, applicable facility-specific service-area authority was supplied. A published county list alone does not establish boundary compliance.",
  ] }
  const ref = JSON.parse(await readFile(path, "utf8"))
  if (ref.hospitalId !== hospital.id || ref.ruleType !== "required_counties" || typeof ref.ruleVersion !== "string" || !ref.ruleVersion.trim()
      || !/^\d{4}-\d{2}-\d{2}$/.test(ref.effectiveFrom) || !/^\d{4}-\d{2}-\d{2}$/.test(ref.effectiveThrough)
      || !Number.isFinite(Date.parse(ref.effectiveFrom)) || !Number.isFinite(Date.parse(ref.effectiveThrough))
      || reviewDate < ref.effectiveFrom || reviewDate > ref.effectiveThrough
      || !Array.isArray(ref.requiredCounties) || !ref.requiredCounties.length
      || ref.requiredCounties.some((c: any) => typeof c !== "string" || !c.trim())
      || !Array.isArray(ref.citations) || !ref.citations.length
      || !ref.applicabilityCitation) throw new Error("Reference lacks a facility-specific rule, effective dates or applicability evidence")
  const source = await prepareReviewSource({ snapshot: ref.snapshot, roles: ["psa_reference"] }, project)
  const evidence = [...ref.citations, ref.applicabilityCitation].map((citation: any) => {
    const passage = source.passages.find(p => p.locator === citation.locator)
    if (!passage || typeof citation.quote !== "string" || normalized(citation.quote).length < 8
        || !normalized(passage.text).includes(normalized(citation.quote))) throw new Error("Reference citation failed source verification")
    return { snapshot_id: source.snapshot.snapshot_id, sourceUrl: source.snapshot.sourceUrl, sha256: source.snapshot.sha256,
      locator: citation.locator, quote: citation.quote }
  })
  if (ref.requiredCounties.some((county: string) => !evidence.some(e => normalized(e.quote).includes(normalized(county))))) {
    throw new Error("Required county is not present in authority evidence")
  }
  // Quote checks prove provenance, not legal applicability or institutional approval.
  return { status: "verified", requiredCounties: ref.requiredCounties, evidence,
    limitations: ["Reference text and hashes verified; independent approval of rule applicability remains required."] }
}
